<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Theme\Application\Usecase\Delete;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;
use Civi\Lughauth\Features\Document\Theme\Application\Service\Visibility\ThemeVisibilityService;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ThemeDeleteUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ThemeVisibilityService $visibility,
        private readonly ThemeWriteGateway $writer,
    ) {
    }

    public function allowDelete(?ThemeRef $ref = null): Allow
    {
        $this->logDebug("Check allow of delete usecase for Theme");
        $span = $this->startSpan("Check allow of delete usecase for Theme");
        try {
            $result = $this->dispatcher->dispatch(new ThemeDeleteAllowDecision(Allow::allowed('delete', 'Allowed to delete by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function delete(string $uid): void
    {
        $this->logDebug("Run delete usecase for Theme");
        $span = $this->startSpan("Run delete usecase for Theme");
        try {
            $ref = new ThemeRef($uid);
            $allow = $this->allowDelete($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to delete Theme');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new ThemeDeleteCheck($original));
            $deleted = $original->delete();
            $this->writer->delete($deleted);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
